import {placeOnBreadboard,placementCandidate,attachPlacement} from './mounting.js';
export const DIODE_EXAMPLES=[{id:'diode-lab',name:'Uno · diyot ve zener ölçümü',tag:'0.7 V / 5.1 V · gerçek yük'},{id:'diode-clip',name:'Uno · diyot sinüs sınırlayıcı',tag:'10 Hz · 50 Ω / 1 kΩ'}];
export const DIODE_SOURCES={'diode-lab':`void setup(){Serial.begin(115200);}void loop(){Serial.print("DIODE ADC=");Serial.print(analogRead(A0));Serial.print(" ZENER_HALF ADC=");Serial.println(analogRead(A1));delay(100);}
`};
DIODE_SOURCES['diode-clip']=`void setup(){Serial.begin(115200);}void loop(){Serial.print("CLIP ADC=");Serial.println(analogRead(A0));delay(7);}
`;
export function makeDiodeProject(base,id){const p=structuredClone(base);p.model=id;p.name=DIODE_EXAMPLES.find(e=>e.id===id).name;p.code=DIODE_SOURCES[id];delete p.firmware;const part=(type,id,params,x,y)=>{const c={id,type,x,y,rotation:0,params};p.components.push(c);return c;},wire=(from,to,color='#14b8a6')=>p.wires.push({id:'diode'+p.wires.length,from,to,color,points:[]});for(const[type,id,x,y]of[['diode','forward',780,350],['zener','clamp',780,440]]){const c=part(type,id,{},x,y);placeOnBreadboard(p,c);if(type==='zener'){delete c.mount;c.x+=8*12.96;attachPlacement(c,placementCandidate(p,c,{radius:.1}));}}for(const[id,ohms,x,y]of[['series',1000,530,160],['limit',1000,820,180],['upper',10000,960,360],['lower',10000,960,450]])part('resistor',id,{ohms},x,y);part('supply','source',{voltage:12},1020,180);wire('uno:5V','series:1','#ef4444');wire('series:2','forward:A');wire('forward:K','uno:GND.1','#64748b');wire('forward:A','uno:A0');wire('source:GND','uno:GND.1','#64748b');wire('source:VCC','limit:1','#ef4444');wire('limit:2','clamp:K');wire('clamp:A','uno:GND.1','#64748b');wire('clamp:K','upper:1');wire('upper:2','lower:1');wire('lower:2','uno:GND.1','#64748b');wire('upper:2','uno:A1');p.settings.measurement={positive:'clamp:K',negative:'clamp:A',current:'clamp:i'};if(id==='diode-clip'){p.components=p.components.filter(c=>!['clamp','source','limit','upper','lower'].includes(c.id));const endpoints=new Set(p.components.map(c=>c.id));p.wires=p.wires.filter(w=>endpoints.has(w.from.split(':')[0])&&endpoints.has(w.to.split(':')[0]));p.wires=p.wires.filter(w=>w.to!=='series:1');part('signalgen','generator',{wave:'sine',frequency:10,offset:2.5,amplitude:2.5,duty:50,enabled:1},960,300);p.wires.push({id:'clip-out',from:'generator:OUT',to:'series:1',color:'#14b8a6',points:[]},{id:'clip-ground',from:'generator:GND',to:'uno:GND.1',color:'#64748b',points:[]});p.settings.measurement={positive:'forward:A',negative:'forward:K',current:'forward:i'};}p.settings.scopeMode='dc';return p;}
